def ruleU2(a_,b_,fc,T):
    H=max(dy for dy,dx in T)+1; W=max(dx for dy,dx in T)+1
    hh,ww=a_.shape; out=a_.copy()
    for r in range(hh-H+1):
        for c in range(ww-W+1):
            cel=[(r+dy,c+dx) for dy,dx in T]
            if all(a_[p]==0 for p in cel):
                for p in cel:
                    if out[p]==0: out[p]=fc
    return out
