def ruleS(a_,b_,fc,T,seedc):
    H=max(d for d,_ in T)+1; W=max(d for _,d in T)+1
    hh,ww=a_.shape; out=a_.copy(); errs=[]
    for r in range(hh-H+1):
        for c in range(ww-W+1):
            cel=[(r+dy,c+dx) for dy,dx in T]
            if all(a_[p] in (0,seedc) for p in cel):
                for p in cel:
                    if a_[p]==0:
                        if b_[p]==fc: out[p]=fc
                        else: errs.append(p)
    return out,errs
for a_,b_,fc,T,sc,nm in [(a,b,8,T1,8,'p1'),(a2,b2,5,T2,5,'p2'),(a3,b3,2,T,2,'p3')]:
    o,e=ruleS(a_,b_,fc,T,sc)
